// Muse Usage Widget for Scriptable (iOS)
// Setup:
//   1. Paste the raw URL of your usage.json (e.g. a GitHub Gist raw URL)
//      into DATA_URL below.
//   2. Add this script in Scriptable, then add a small/medium Scriptable
//      widget to the Home Screen and select this script.
// The JSON is produced on the Muse VM by update-usage.sh, e.g.:
//   { "plan": "Power", "usedPercent": 25, "remainingPercent": 75,
//     "resetText": "Nov 12 at 7:24 PM JST",
//     "resetAt": "2026-11-12T19:24:00+09:00",
//     "updatedAt": "2026-11-09T15:24:00+09:00" }

// Yukari Edition: usage data is read from the GitHub Gist raw URL below.
// Paste your Gist raw URL (…/raw/usage.json) between the quotes.
const DATA_URL = "https://raw.githubusercontent.com/hirogturtle-cell/muse-usage/main/ai-usage.json";

async function fetchUsage() {
  const fm = FileManager.local();
  const cachePath = fm.joinPath(fm.cacheDirectory(), "muse-usage.json");
  // PHOTO-ONLY MODE: no data URL configured -> use the built-in sample values
  // so the widget shows Yukari's photo without any network access.
  if (!DATA_URL) {
    return {
      plan: "Power",
      usedPercent: 31,
      remainingPercent: 69,
      resetText: "Nov 12 at 7:24 PM JST",
      resetAt: "2026-11-12T19:24:00+09:00",
      updatedAt: "2026-11-10T08:02:39+09:00"
    };
  }
  try {
    const req = new Request(DATA_URL);
    req.timeoutInterval = 10;
    const data = await req.loadJSON();
    fm.writeString(cachePath, JSON.stringify(data));
    return data;
  } catch (e) {
    // Offline etc.: fall back to the last cached copy.
    if (fm.fileExists(cachePath)) {
      return JSON.parse(fm.readString(cachePath));
    }
    throw e;
  }
}

const YUKARI_B64 = "";

function daysUntil(dateStr) {
  if (!dateStr) return null;
  const ms = new Date(dateStr).getTime() - Date.now();
  return Math.max(0, Math.ceil(ms / 86400000));
}

function buildStats(w, d) {
  const title = w.addText("Muse");
  title.font = Font.boldSystemFont(13);
  title.textColor = new Color("#9ca3af");

  w.addSpacer(4);

  const pct = w.addText(`${d.remainingPercent}% left`);
  pct.font = Font.boldSystemFont(26);
  pct.textColor = d.usedPercent >= 90 ? new Color("#f87171") : Color.white();

  const used = w.addText(`Weekly ${d.usedPercent}% used · ${d.plan || ""}`);
  used.font = Font.systemFont(11);
  used.textColor = new Color("#d1d5db");

  w.addSpacer(4);

  const days = daysUntil(d.resetAt);
  const resetLine = days !== null
    ? `Resets in ${days} day${days === 1 ? "" : "s"}`
    : `Resets ${d.resetText || ""}`;
  const reset = w.addText(resetLine);
  reset.font = Font.systemFont(11);
  reset.textColor = new Color("#9ca3af");

  const upd = w.addText(`Updated ${String(d.updatedAt || "").slice(5, 16).replace("T", " ")}`);
  upd.font = Font.systemFont(9);
  upd.textColor = new Color("#6b7280");
}


function warnColor(remaining) {
  if (remaining == null) return new Color('#9ca3af');
  if (remaining <= 10) return new Color('#f87171');
  if (remaining <= 25) return new Color('#facc15');
  return Color.white();
}
function fmtReset(s) {
  if (!s || !s.resetAt) return '';
  const days = daysUntil(s.resetAt);
  const d = new Date(s.resetAt);
  const wd = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][d.getDay()];
  const hh = String(d.getHours()).padStart(2,'0');
  const mm = String(d.getMinutes()).padStart(2,'0');
  return (d.getMonth()+1) + '/' + d.getDate() + ' (' + wd + ') ' + hh + ':' + mm + (days !== null ? ' · in ' + days + 'd' : '');
}
function svcRow(w, s) {
  const row = w.addStack();
  row.layoutHorizontally();
  const name = row.addText(s.name);
  name.font = Font.boldSystemFont(13);
  name.textColor = Color.white();
  name.lineLimit = 1;
  row.addSpacer();
  if (s.remainingPercent == null) {
    const na = row.addText('n/a');
    na.font = Font.boldSystemFont(13);
    na.textColor = new Color('#9ca3af');
  } else {
    const pct = row.addText(s.remainingPercent + '% left');
    pct.font = Font.boldSystemFont(13);
    pct.textColor = warnColor(s.remainingPercent);
    pct.lineLimit = 1;
  }
  const sub = [];
  if (s.plan) sub.push(s.plan);
  const rs = fmtReset(s);
  if (rs) sub.push('resets ' + rs);
  if (s.note) sub.push(s.note);
  if (sub.length) {
    const t = w.addText('  ' + sub.join(' · '));
    t.font = Font.systemFont(9);
    t.textColor = new Color('#9ca3af');
    t.lineLimit = 1;
  }
  if (s.fiveHourRemainingPercent != null) {
    const t = w.addText('  5h ' + s.fiveHourRemainingPercent + '% left');
    t.font = Font.systemFont(9);
    t.textColor = new Color('#d1d5db');
    t.lineLimit = 1;
  }
}
function servicesOf(d) {
  if (d && Array.isArray(d.services) && d.services.length) return d.services;
  return [{
    name: 'Muse', plan: d.plan || '',
    usedPercent: d.usedPercent, remainingPercent: d.remainingPercent,
    resetAt: d.resetAt || '', resetText: d.resetText || ''
  }];
}

function buildWidget(d) {
  const w = new ListWidget();
  w.backgroundColor = new Color("#111827");
  w.setPadding(12, 14, 12, 14);


  // LARGE: Yukari fills the widget; usage rides in a small bar at the bottom.
  if (config.widgetFamily === "large") {
    try {
      const bg = Image.fromData(Data.fromBase64String(YUKARI_B64));
      w.backgroundImage = bg;
    } catch (e) {}
    w.setPadding(10, 12, 10, 12);
    w.addSpacer();
    const bar = w.addStack();
    bar.layoutHorizontally();
    bar.backgroundColor = new Color("#000000", 0.45);
    bar.cornerRadius = 8;
    bar.setPadding(6, 10, 6, 10);
    const t = bar.addText(`Muse  ${d.remainingPercent}% left \u00b7 Weekly ${d.usedPercent}% used \u00b7 ${d.plan || ""}`);
    t.font = Font.boldSystemFont(13);
    t.textColor = Color.white();
    const svcsL = servicesOf(d);
    if (svcsL.length > 1) {
      const extra = svcsL.slice(1).map(s => s.name + ' ' + (s.remainingPercent == null ? 'n/a' : s.remainingPercent + '%')).join(' · ');
      if (extra) {
        const t2 = bar.addText('  · ' + extra);
        t2.font = Font.systemFont(11);
        t2.textColor = new Color('#d1d5db');
      }
    }
    return w;
  }

  // Yukari photo on the left; usage stats on the right (medium layout).
  if (config.widgetFamily !== "small") {
    const row = w.addStack();
    row.layoutHorizontally();
    try {
      const img = row.addImage(Image.fromData(Data.fromBase64String(YUKARI_B64)));
      img.imageSize = new Size(96, 144);
      img.cornerRadius = 8;
    } catch (e) {}
    row.addSpacer(12);
    const col = row.addStack();
    col.layoutVertically();
    const svcs = servicesOf(d);
    svcs.forEach((s, i) => { if (i > 0) col.addSpacer(5); svcRow(col, s); });
    col.addSpacer(4);
    const upd2 = col.addText('Updated ' + String(d.updatedAt || '').slice(5, 16).replace('T', ' '));
    upd2.font = Font.systemFont(8);
    upd2.textColor = new Color('#6b7280');
    return w;
  }

  const svcsS = servicesOf(d);
  svcsS.forEach((s, i) => { if (i > 0) w.addSpacer(5); svcRow(w, s); });

  // Ask iOS to refresh roughly every 15 minutes (iOS decides the real cadence).
  w.refreshAfterDate = new Date(Date.now() + 15 * 60 * 1000);
  return w;
}

const data = await fetchUsage();
const widget = buildWidget(data);
if (config.runsInWidget) {
  Script.setWidget(widget);
} else {
  widget.presentLarge();
}
Script.complete();
